import type { ReactNode } from 'react'
import './Popover.css'

export type PopoverProps = {
  /** Кнопка, что открывает (один элемент, умеющий ref) */
  trigger: ReactNode
  /** Содержимое всплывашки */
  children: ReactNode
  side?: 'top' | 'right' | 'bottom' | 'left'
  align?: 'start' | 'center' | 'end'
  /** Подпись для скринридера, если в содержимом нет заголовка */
  label?: string
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Фокус внутрь при открытии (по умолчанию да). false — фокус остаётся на кнопке, кольца на первом пункте нет (меню «Мои игры») */
  autoFocus?: boolean
  className?: string
}

/** Всплывашка по клику (Radix Popover; вид — меню «Мои игры» news/PageHead .page-head__pop).
 *  Клавиатура: Enter/Space открывает, фокус уходит внутрь, Esc и клик мимо закрывают и возвращают фокус; aria-expanded / aria-controls — от Radix. */
export function Popover({ trigger, children, side = 'bottom', align = 'start', label, open, defaultOpen, onOpenChange, autoFocus = true, className }: PopoverProps) {
  return (
    <R.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange}>
      <R.Trigger asChild>{trigger}</R.Trigger>
      <R.Portal>
        <R.Content className={'popover' + (className ? ' ' + className : '')} side={side} align={align} sideOffset={6} collisionPadding={8} aria-label={label}
          onOpenAutoFocus={autoFocus ? undefined : (e) => e.preventDefault()}>
          {children}
        </R.Content>
      </R.Portal>
    </R.Root>
  )
}
