import { caseArg, stateArg } from '../../storyArgs'
import { statusArgTypes } from '@/atoms/WidgetStatus'
import { MapTab } from './Map'

/** Вкладка карты целиком — как главная колонка страницы матча в окне 1440 × 900: 1040 × 766 (под шапкой) */
