  const [pick, set] = useState(p.pick ?? null), [i, setI] = useState(p.index ?? 0)
  const x = p.which === 'new' ? incomingPrediction() : linePredictions()[p.total && p.total > 1 ? i : p.which === 'die' ? 1 : 0]
