      const w = W - 1, h = H - 1, r = Math.min(7, w / 2, h / 2), P = 2 * (w + h) - 8 * r + 2 * Math.PI * r, s0 = (1 - f) * P, F = P * 0.3, step = 0.5
      g.save(); g.translate(.5, .5); g.lineWidth = 1; g.strokeStyle = muted ? getComputedStyle(cv).getPropertyValue('--pred-ring-m').trim() : getComputedStyle(cv).getPropertyValue('--pred-ac').trim()
      g.globalAlpha = .14; g.beginPath(); for (let s = Math.min(P, s0 + F); s <= P; s += 2) g.lineTo(...ringPt(s, w, h, r)); g.lineTo(...ringPt(P, w, h, r)); g.stroke()
