import type { FeedCardData, FeedDay } from '../../data/view'
import './Feed.css'

export type FeedProps = {
  days: FeedDay[]
  /** Сколько ещё подгрузит «Показать ещё» и сколько всего осталось; 0 — кнопки нет */
  more: number
  rest: number
  onMore?: () => void
  /** Состояние данных: loading — день и 4 карточки заглушками, error — «Не удалось загрузить» */
  status?: WidgetStatus
  onRetry?: () => void
}

/** Карточка ленты (лаба w-match-news row3): слева фото 168 (или лого команд «×»), сверху время моно и «Tier 1», заголовок с плашками в 3 строки. */
export function FeedCard({ href, cover, time, tier1, parts }: FeedCardData) {
  return (
    <a className="feed__c" href="#" onClick={(e) => e.preventDefault()}>
      {'img' in cover ? <img className="feed__im" src={cover.img} alt="" loading="lazy" />
        : <span className="feed__im feed__lg">{cover.logos.map((l, i) => <span key={i} className="feed__lgi">{i > 0 && <i>×</i>}<img src={l} alt="" /></span>)}</span>}
      <span className="feed__b">
        <span className="feed__m"><time>{time}</time>{tier1 && <TierTag tier={1} />}</span>
        <span className="feed__t"><Title look="chip" parts={parts} /></span>
      </span>
    </a>
  )
}

/** Лента ниже «Главного» / колонок матча: по дням, карточки по две в ряд, свежие сверху; «Показать ещё 16 из N». */
export function Feed({ days, more, rest, onMore, status = 'ready', onRetry }: FeedProps) {
  if (status === 'error') return <div className="feed"><StatusError grow onRetry={onRetry} /></div>
  if (status === 'loading') return (
    <div className="feed" aria-busy="true">
      <div className="feed__day">
        <div className="feed__dh"><Skeleton width={120} height={16} /></div>
        <div className="feed__g">{Array.from({ length: 4 }, (_, i) => (
          <span key={i} className="feed__c"><Skeleton shape="block" width={168} height={94.5} style={{ flex: 'none' }} /><span className="feed__b"><SkeletonLines gap={8} n={3} h={14} widths={[60, '100%', '70%']} /></span></span>
        ))}</div>
      </div>
    </div>
  )
  return (
    <div className="feed">
      {days.map((d) => (
        <div key={d.title} className="feed__day">
          <div className="feed__dh"><b>{d.title}</b><small>{d.count} новостей</small></div>
          <div className="feed__g">{d.cards.map((c) => <FeedCard key={c.href} {...c} />)}</div>
        </div>
      ))}
      {rest > 0 && <Button variant="secondary" size="xl" className="feed__more" onClick={onMore}>Показать ещё {more} из {rest}</Button>}
    </div>
  )
}
