const TIER: Record<string, TourTier> = { S: 1, A: 2, B: 3 }
const dm = (s: string) => (s ? s.slice(8, 10) + '.' + s.slice(5, 7) : '')

/** Все турниры в порядке лабы: TI первым, дальше — как в базе */
export function tournaments(): TourItem[] {
  const all = Object.values(DB().data.tours) as unknown as TourFull[]
  const ti = all.find((t) => t.id === TI)
  const base = (t: TourFull): TourItem => ({ id: t.id, name: t.name, st: t.state, tier: TIER[t.tier] ?? null, from: dm(t.from), to: dm(t.to), prize: t.prize, stage: t.stage || 'Скоро', fmt: t.format || 'groups', rule: '', teams: t.teams || [] })
  const out: TourItem[] = []
  if (ti) {
    const st = (ti.standings || []).slice().sort((a, b) => a.place - b.place)
    out.push({ ...base(ti), fmt: 'groups', rule: TI_RULE, groups: { A: st.map((x) => ({ team: x.team, w: +x.wl.split('-')[0], l: +x.wl.split('-')[1] })) }, zones: { up: [1, 2, 3], down: [14, 15, 16] }, teams: [] })
  }
  return out.concat(all.filter((t) => t.id !== TI).map(base))
}

/** Лого игры (Dota 2) из базы */
export const gameLogo = () => img((DB().data.games as { id: string; logo: string }[] | undefined)?.find((g) => g.id === 'dota2')?.logo)

/** «Групповой этап · день 4» → «День 4 · Групповой этап»; без «Старт …» / «… завершён» */
export function stageLine(t: TourItem) {
  const p = t.stage.split(' · '), d = p.findIndex((x) => /^день \\d+/i.test(x))
  if (d > 0) { const day = p.splice(d, 1)[0]; p.unshift(day[0].toUpperCase() + day.slice(1)) }
  return p.filter((x) => x && !/^(Старт|завершён) /i.test(x)).map((x) => x[0].toUpperCase() + x.slice(1)).join(' · ')
}

/** Форма — 5 последних матчей. В данных её нет: пример, стабильный по имени команды (как в лабе) */
export function form(name: string): ('w' | 'l')[] {
  let h = 0
  for (const c of name) h = (h * 31 + c.charCodeAt(0)) >>> 0
  return [...Array(5)].map((_, i) => ((h >> (i * 3)) % 5 < 3 ? 'w' : 'l'))
}
