            <p className="tfmt__rules">{s.rules.map((r, i) => <Fragment key={i}>{i > 0 && ' · '}{r.split(/\\*\\*(.+?)\\*\\*/).map((x, j) => (j % 2 ? <mark key={j} className="tfmt__mark">{x}</mark> : x))}</Fragment>)}</p>
