import { Widget } from '@/atoms/Widget'
import { heroStats, type HeroStat } from '../../data/heroes'
import type { TourKey } from '../../state'
import { SkeletonLines, StatusError, type WidgetStatus } from '@/atoms/WidgetStatus'
import './HeroStats.css'

export type HeroSortKey = 'n' | 'p' | 'pv' | 'pwr' | 'pt' | 'r' | 'rv' | 'rwr' | 'd' | 'dv' | 'dwr' | 'b' | 'bt' | 'pb' | 'pbt'
export type HeroStatsProps = {
  tour: TourKey
  /** Сортировка по умолчанию — «Пик + бан · Всего» */
  sort?: HeroSortKey
  /** Направление: −1 — по убыванию, 1 — по возрастанию */
  dir?: 1 | -1
  /** Состояние данных (по умолчанию ready) */
  status?: WidgetStatus
  /** «Повторить» в состоянии error */
  onRetry?: () => void
}

const pct = (a: number, b: number) => (b ? Math.round((a / b) * 100) + '%' : '—')
const tone = (w: number, n: number) => { if (!n) return ''; const d = w / n - 0.5; return d >= 0.2 ? 'w2' : d > 0 ? 'w1' : d <= -0.2 ? 'l2' : d < 0 ? 'l1' : '' }
